def _version_parts(value: str) -> tuple[int, ...] | None:
    match = re.search(r"[0-9]+(?:[.][0-9]+){1,3}", value)
    if match is None:
        return None
    try:
        return tuple(int(part) for part in match.group(0).split("."))
    except ValueError:
        return None


def _explicit_build(value: str) -> int | None:
    dotted = _version_parts(value)
    if dotted is not None and len(dotted) == 4:
        return dotted[3]
    match = re.search(
        r"(?:build(?:[ ]+(?:number|no[.]?))?|development[ ]+build|开发版本|版本)[ ]*[:：#]?[ ]*([0-9]+)",
        value, re.IGNORECASE,
    )
    if match is None:
        return None
    return int(match.group(1))


def _pad_product_version(parts: Sequence[int]) -> tuple[int, int, int]:
    if not 2 <= len(parts) <= 3:
        raise ValueError("COMSOL product version must have two or three components")
    return tuple([*parts, *([0] * (3 - len(parts)))])  # type: ignore[return-value]


def _parse_version_declaration(value: str) -> tuple[tuple[int, int, int], int]:
    parts = _version_parts(value)
    build = _explicit_build(value)
    if parts is None or build is None:
        raise ValueError("COMSOL version declaration has no explicit build")
    if len(parts) == 4:
        if build != parts[3]:
            raise ValueError("COMSOL version declaration contains conflicting builds")
        family = parts[:3]
    else:
        family = parts
    return _pad_product_version(family), build


def _reported_comsol_version(worker: Any) -> str:
    """Read ModelUtil version through the bound Worker facade."""
    getter = getattr(worker, "getComsolVersion", None)
    if callable(getter):
        return getter()
    # Compatibility for older fixtures/Worker facades. Production
    # PersistentJavaWorker exposes the verified ModelUtil call directly.
    return worker.client().getComsolVersion()


def _current_version(worker: Any) -> str:
    try:
        version = _reported_comsol_version(worker)
    except Exception as exc:
        raise PreWriteRefusal("RUNTIME_VERSION_UNAVAILABLE", "the attached Worker did not report its COMSOL version",
                              details={"cause_type": type(exc).__name__}) from exc
    if not isinstance(version, str) or not version.strip():
        raise PreWriteRefusal("RUNTIME_VERSION_UNAVAILABLE", "the attached Worker returned no COMSOL version")
    reported = version.strip()
    reported_parts = _version_parts(reported)
    if reported_parts is None:
        raise PreWriteRefusal("RUNTIME_VERSION_UNAVAILABLE", "Worker version did not expose a COMSOL release token")
    reported_family = _pad_product_version(reported_parts[:3] if len(reported_parts) == 4 else reported_parts)
    reported_build = _explicit_build(reported)
    paths = getattr(worker, "paths", None)
    root = getattr(paths, "comsol_root", None)
    if root is None:
        raise PreWriteRefusal("RUNTIME_VERSION_UNAVAILABLE", "the attached Worker installation path is unavailable")
    try:
        from ._runtime_installation import inspect_installation, runtime_id_for_root
        inspected = inspect_installation(runtime_id_for_root(root))
        installation = inspected.get("installation") if isinstance(inspected, Mapping) else None
        release = installation.get("version") if isinstance(installation, Mapping) else None
        build_row = installation.get("build") if isinstance(installation, Mapping) else None
        if (inspected.get("status") != "OBSERVED" or not isinstance(release, Mapping)
                or release.get("status") != "OBSERVED" or not isinstance(release.get("value"), str)
                or not isinstance(build_row, Mapping) or build_row.get("status") != "OBSERVED"
                or type(build_row.get("value")) is not int):
            raise ValueError("attached installation release/build identity is not observed")
        family = _pad_product_version(tuple(int(part) for part in release["value"].split(".")))
        build = int(build_row["value"])
    except Exception as exc:
        raise PreWriteRefusal("RUNTIME_VERSION_UNAVAILABLE", "the attached Worker install lacks an exact observed release and build",
                              details={"cause_type": type(exc).__name__}) from exc
    if reported_family != family or (reported_build is not None and reported_build != build):
        raise PreWriteRefusal("RUNTIME_VERSION_MISMATCH", "Worker version readback conflicts with its bound installation identity",
                              details={"worker_version": reported, "installation_version": release.get("value"),
                                       "installation_build": build})
    return f"{family[0]}.{family[1]}.{family[2]}.{build}"

def _canonical_directory(value: str | os.PathLike[str]) -> Path:
    text = os.fspath(value)
    if not text or any(ord(char) < 32 for char in text):
        raise RuntimeInstallationError("installation root must be a non-empty path without control characters")
    path = Path(text).expanduser()
    if not path.is_absolute():
        raise RuntimeInstallationError("installation roots must be absolute paths")
    try:
        resolved = path.resolve(strict=True)
    except OSError as exc:
        raise RuntimeInstallationError("installation root is missing or inaccessible") from exc
    if not resolved.is_dir():
        raise RuntimeInstallationError("installation root is not a directory")
    return resolved


def runtime_id_for_root(root: str | os.PathLike[str]) -> str:
    """Return a stable local identifier that binds the canonical install path."""
    canonical = _canonical_directory(root)
    return "comsol-install:" + quote(str(canonical), safe="")


def _root_from_runtime_id(runtime_id: str) -> Path:
    if not isinstance(runtime_id, str) or not runtime_id.startswith("comsol-install:"):
        raise RuntimeInstallationError("runtime_id is not a local COMSOL installation identifier")
    encoded = runtime_id.removeprefix("comsol-install:")
    if not encoded:
        raise RuntimeInstallationError("runtime_id does not identify an installation path")
    decoded = unquote(encoded)
    if any(ord(char) < 32 for char in decoded):
        raise RuntimeInstallationError("runtime_id contains control characters")
    try:
        path = _canonical_directory(decoded)
    except RuntimeInstallationError:
        raise
    if runtime_id_for_root(path) != runtime_id:
        raise RuntimeInstallationError("runtime_id path is not in canonical encoded form")
    return path

def _worker_key(identity: Mapping[str, Any]) -> str:
    value = identity.get("runtime_id") or identity.get("worker_instance_id")
    if not isinstance(value, str) or not value: raise RuntimeStateError("worker identity requires runtime_id or worker_instance_id")
    return value


def save_runtime_state(store: Any, ledger: SessionLedger, worker_identity: Mapping[str, Any], active_tickets: Iterable[ExecutionTicket] = ()) -> dict[str, Any]:
    """Persist all ledger fields; ticket metadata is retained for UNKNOWN recovery."""
    identity = dict(worker_identity); runtime_id = _worker_key(identity)
    models = {}
    for tag, state in ledger._models.items():
        models[tag] = {"ref": state.ref.as_dict(), "revision": state.revision, "fingerprint": state.fingerprint,
                       "external_event_counter": state.external_event_counter, "observed_external_event_counter": state.observed_external_event_counter,
                       "dirty": state.dirty, "retired": state.retired, "active_operation_id": state.active_operation_id,
                       "ownership": ledger.model_ownership.get(tag, "user_owned")}
    tickets = [{"operation_id": t.operation_id, "request_id": t.request_id, "request_hash": t.request_hash, "operation": t.operation,
                "model_ref": t.model_ref.as_dict(), "expected_revision": t.expected_revision,
                "external_event_counter": t.external_event_counter, "fingerprint": t.fingerprint} for t in active_tickets]
    state = {"schema_version": RUNTIME_STATE_SCHEMA_VERSION, "worker_identity": identity, "session_id": ledger.session_id,
             "server_instance_id": ledger.server_instance_id, "server_ownership": ledger.server_ownership,
             "permissions": sorted(ledger.permissions), "generations": dict(ledger._generations), "models": models, "active_tickets": tickets}
    _put(store, "sessions", ledger.session_id, state); _put(store, "runtimes", runtime_id, state)
    return state

