def _license_api_call(worker: Any, method: str, arguments: Sequence[Any],
                      *, log: "_CallLog | None" = None) -> dict[str, Any]:
    """Call one license-surface API through the persistent Worker, once.

    The Worker's own command channel is preferred because that is where the
    Java allow-list lives: a refused method is then observed
    (``MODEL_UTIL_METHOD_REJECTED``) instead of being assumed from a source
    read.  A Python client facade that exposes the same method is used only
    when the Worker has no command channel at all.  No retry happens here: a
    license answer is never approximated.
    """
    if log is not None:
        log.record(method)
    if method in SEAT_CONSUMING_METHODS:
        raise ExecutionContractError(
            "PERMISSION_DENIED",
            f"{method} checks out a license seat and is never called by a license probe",
        )
    submit = getattr(worker, "submit", None)
    if callable(submit):
        try:
            reply = submit(
                WORKER_MODELUTIL_COMMAND,
                {"method": method, "args": [argument for argument in arguments]},
            )
        except Exception as exc:  # noqa: BLE001 - a transport/driver failure is reported, never guessed
            return _refusal(
                error_code_of(exc),
                f"Worker {method} call failed: {type(exc).__name__}",
                method,
                channel=f"{WORKER_MODELUTIL_COMMAND} command",
                allowlist=allowlist_rejected(exc) or _is_allowlist_refusal(error_code_of(exc), exc),
            )
        if not isinstance(reply, Mapping):
            return _refusal(
                "EXECUTION_STATE_UNKNOWN",
                f"Worker {method} reply is not an object",
                method,
                channel=f"{WORKER_MODELUTIL_COMMAND} command",
                allowlist=False,
            )
        if reply.get("ok") is True:
            return {
                "ok": True,
                "value": reply.get("result"),
                "code": None,
                "message": None,

              log: "_CallLog | None" = None) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
"""One non-checkout license query per product; unresolved rows are returned.

A row carries a value only when the engine returned a real boolean.  A row
the probe could not resolve is returned separately so the caller can refuse
the whole request instead of reporting a partially answered license state.
"""
rows: list[dict[str, Any]] = []
unresolved: list[dict[str, Any]] = []
for product in products:
    # One product per query, packed as the ``String[]`` the varargs parameter
    # declares (C05): a bare scalar does not marshal to ``hasProduct(String...)``.
    argument = string_array_value([product])
    outcome = _license_api_call(worker, "hasProduct", [argument], log=log)
    if not outcome["ok"]:
        unresolved.append(
            {
                "product": product,
                "probe_error": {
                    "code": outcome["code"],
                    "message": outcome["message"],
                    "allowlist_entry_required": outcome["allowlist_entry_required"],
                    "failure_kind": _probe_failure_kind(
                        outcome["code"], outcome["allowlist_entry_required"]
                    ),
                    "argument": argument,
                },
            }
        )
        continue
    if type(outcome["value"]) is not bool:
        unresolved.append(
            {
                "product": product,
                "probe_error": {
                    "code": "EXECUTION_STATE_UNKNOWN",
                    "message": "ModelUtil.hasProduct() did not return a boolean",
                    "allowlist_entry_required": None,
                    "failure_kind": "non_boolean_answer",
                    "argument": argument,
                },
            }
        )
        continue
    rows.append(
        {
            "product": product,
            "hasProduct": outcome["value"],
            "product_label": FEATURE_STRING_PRODUCTS.get(product),
            "documented_feature_string": product in DOCUMENTED_FEATURE_STRINGS,
            "source": "ModelUtil.hasProduct(String)",
            "channel": outcome["channel"],
            "argument_shape": {
                "count": len(argument["data"]),
                "java_signature": argument["java_signature"],
            },
        }

private static final Set<String> MODEL_UTIL = new HashSet<>(Arrays.asList(
    "create", "load", "loadCopy", "model", "remove", "tags", "uniquetag", "modelsUsedByOtherClients",
    "getComsolVersion",
    // G3 runtime licence probe: documented, non-seat-consuming query
    // (javap com.comsol.model.util.ModelUtil; KB Programming Reference p.42).
    "hasProduct"));

private Object connect(Map<String, Object> request) {
  String host = string(request.get("host")); int port = (int) number(request.get("port"), -1);
  if (host.isEmpty() || port < 1 || port > 65535) throw new IllegalArgumentException("host and port required");
  String canonicalHost;
  try { canonicalHost = InetAddress.getByName(host).getHostAddress(); }
  catch (IOException exc) { throw new WorkerFailure("ENGINE_UNRESPONSIVE", "server hostname could not be resolved"); }
  acquireServerLock(canonicalHost + ":" + port);
  boolean encrypted = Boolean.TRUE.equals(request.get("encrypted"));
  // Credentials are accepted only as in-memory request values and never returned/logged.
  String user = string(request.get("user")), pass = string(request.get("password"));
  try {
    if (user.isEmpty() && pass.isEmpty()) ModelUtil.connect(host, port, encrypted);
    else ModelUtil.connect(host, port, encrypted, user, pass);
  } catch (RuntimeException exc) { releaseServerLock(); throw exc; }
  ModelUtil.setModelChangedHandler(new ChangeHandler());
  connected = true; serverIdentity = host + ":" + port; generation.incrementAndGet(); handles.clear();
  return map("connected", true, "server", serverIdentity, "generation", generation.get(), "instance_id", instanceId, "engine_version", ModelUtil.getComsolVersion());
}

